#!/usr/bin/env bash
# Run every datapath unit TB against spec-formula reference vectors; prints PASS/FAIL per unit.
#   src_int8/tb/run_unit.sh [build_dir]      (default src_int8/tb/build; needs iverilog + python3)
# Exit status 0 only if the generated NLU ROM matches the spec tables and every unit passes.
set -u
SRC=$(cd "$(dirname "$0")/.." && pwd)
ROOT=$(dirname "$SRC")
BUILD=${1:-$SRC/tb/build}
mkdir -p "$BUILD"
cd "$ROOT"
fail=0
PY=${PYTHON:-python3}
$PY -c 'import numpy' 2>/dev/null || PY=/usr/bin/python3   # the nix python has no numpy

# the ROM RTL is generated by team A (scripts/gen_nlu_rom.py from golden/ops/nlu.py); check its
# 340 words against the spec 5.1 tables computed independently in tb/ref/nlu_ref.py
$PY -m src_int8.tb.ref.check_rom || fail=1

$PY -m src_int8.tb.ref.vectors "$BUILD/vec" || exit 1

RTL=$(sed -e '/^\/\//d' -e "s|^|$SRC/rtl/|" "$SRC/rtl/units.f")
for tb in rsh sat lane wb nlu; do
    vvp_out="$BUILD/tb_$tb.vvp"
    if ! iverilog -g2012 -Wall -I "$SRC/rtl/nonlin" -I "$SRC/tb/common" -s "tb_$tb" -o "$vvp_out" \
            $RTL "$SRC/tb/unit/tb_$tb.sv" 2>"$BUILD/tb_$tb.compile.log"; then
        echo "FAIL $tb: compile error (see $BUILD/tb_$tb.compile.log)"; fail=1; continue
    fi
    out=$(vvp -n "$vvp_out" "+VEC=$BUILD/vec/$tb.hex" | grep -E '^(PASS|FAIL|MISMATCH)')
    echo "$out"
    grep -q '^PASS' <<<"$out" || fail=1
done
exit $fail
